const HOME=[48.357222,35.100556],M_DEG=111319.49,tiles=new Map();let redrawQueued=false;
function queueRedraw(){if(redrawQueued)return;redrawQueued=true;requestAnimationFrame(()=>{redrawQueued=false;if(P.data)draw();});}
function tile(z,tx,ty){const key=z+'/'+tx+'/'+ty;let t=tiles.get(key);if(!t){if(tiles.size>400)tiles.delete(tiles.keys().next().value);const img=new Image();t={img,ok:false};img.onload=()=>{t.ok=true;queueRedraw();};img.src='https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/'+z+'/'+ty+'/'+tx;tiles.set(key,t);}return t.ok?t.img:null;}
function drawTiles(g,w,h,v,k,X,Y){const [lat0,lon0]=HOME,c0=Math.cos(lat0*Math.PI/180),z=Math.max(3,Math.min(17,Math.ceil(Math.log2(156543.03392*c0*k)))),N=2**z;
 const lat=n=>lat0+n/M_DEG,lon=e=>lon0+e/(M_DEG*c0),mx=l=>(l+180)/360*N,my=la=>{const s=Math.sin(la*Math.PI/180);return(.5-Math.log((1+s)/(1-s))/(4*Math.PI))*N;};
 const lonT=tx=>tx/N*360-180,latT=ty=>Math.atan(Math.sinh(Math.PI-2*Math.PI*ty/N))*180/Math.PI,e1=v.e0+w/k,n1=v.n0+h/k;
 const x0=Math.max(0,Math.floor(mx(lon(v.e0)))),x1=Math.min(N-1,Math.floor(mx(lon(e1)))),y0=Math.max(0,Math.floor(my(lat(n1)))),y1=Math.min(N-1,Math.floor(my(lat(v.n0))));
 if((x1-x0+1)*(y1-y0+1)>80)return;
 for(let tx=x0;tx<=x1;tx++)for(let ty=y0;ty<=y1;ty++){const img=tile(z,tx,ty);if(!img)continue;const eA=(lonT(tx)-lon0)*M_DEG*c0,eB=(lonT(tx+1)-lon0)*M_DEG*c0,nA=(latT(ty)-lat0)*M_DEG,nZ=(latT(ty+1)-lat0)*M_DEG;g.drawImage(img,X(eA),Y(nA),X(eB)-X(eA)+.7,Y(nZ)-Y(nA)+.7);}}
function homeAndCredit(x,w,h,X,Y){x.fillStyle='#ff4d4d';x.strokeStyle='#fff';x.lineWidth=2;x.beginPath();x.arc(X(0),Y(0),5,0,6.2832);x.fill();x.stroke();x.font='bold 11px IBM Plex Mono,monospace';x.fillStyle='#fff';x.shadowColor='#000';x.shadowBlur=4;x.textAlign='left';x.textBaseline='alphabetic';x.fillText(tr('homeName'),X(0)+9,Y(0)-7);x.textAlign='right';x.font='10px IBM Plex Mono,monospace';x.fillStyle='rgba(255,255,255,.82)';x.fillText('Esri, Maxar, Earthstar Geographics',w-6,h-6);x.shadowBlur=0;x.textAlign='left';}
