function at(run,key,t){const a=run.d[key];if(!a)return null;const f=Math.max(0,Math.min(a.length-1,t/run.d.step)),i=Math.floor(f),j=Math.min(a.length-1,i+1);return a[i]+(a[j]-a[i])*(f-i);}
function stepAt(run,key,t){const a=run.d[key];return a?a[Math.max(0,Math.min(a.length-1,Math.round(t/run.d.step)))]:null;}
function prep(c){const r=c.getBoundingClientRect(),dpr=window.devicePixelRatio||1,w=Math.max(10,r.width),h=Math.max(10,r.height);if(c.width!==Math.round(w*dpr)||c.height!==Math.round(h*dpr)){c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);}const x=c.getContext('2d');x.setTransform(dpr,0,0,dpr,0,0);x.clearRect(0,0,w,h);return{x,w,h};}
function niceStep(range,n){const raw=range/n,p=Math.pow(10,Math.floor(Math.log10(raw))),f=raw/p;return(f<1.5?1:f<3?2:f<7?5:10)*p;}
function ticks(a,b,n){const s=niceStep(b-a,n),o=[];for(let v=Math.ceil(a/s-1e-9)*s;v<=b+1e-9;v+=s)o.push(+v.toFixed(10));return o;}
