 if(df.pwd){const names=['LOST','ZERO','FROZEN','DISAGREE'],rh=22;x.textAlign='right';x.textBaseline='middle';names.forEach((n,i)=>{x.fillStyle=MUTE;x.fillText(n,L-4,Tp+i*rh+rh/2-6);});
  runs().forEach((r,ri)=>{const a=r.d.pwd;if(!a)return;x.fillStyle=COL[r.id];for(let k=0;k<4;k++){let s=-1;for(let i=0;i<=a.length;i++){const on=i<a.length&&(a[i]&(1<<k));if(on&&s<0)s=i;if(!on&&s>=0){const x0=TX(s*r.d.step),x1=TX(i*r.d.step);x.globalAlpha=.85;x.fillRect(x0,Tp+k*rh+2+ri*5,Math.max(2,x1-x0),5);x.globalAlpha=1;s=-1;}}}});marks();cur();return;}
 let lo=1e18,hi=-1e18;const sers=[];
 if(df.wind){const r0=runs()[0],tr0={pts:[],col:TRUTH,lw:2};for(let i=0;i<r0.d.n;i++)tr0.pts.push([i*r0.d.step,windVal(r0,df.wind,i*r0.d.step,false)]);sers.push(tr0);for(const r of runs())if(r.d.wen){const s={pts:[],col:COL[r.id],lw:1.6};for(let i=0;i<r.d.n;i++)s.pts.push([i*r.d.step,windVal(r,df.wind,i*r.d.step,true)]);sers.push(s);}}
 else{for(const r of runs())for(const k of df.series(r)){if(!r.d[k])continue;const pts=[];for(let i=0;i<r.d.n;i++)pts.push([i*r.d.step,r.d[k][i]]);sers.push({pts,col:COL[r.id],lw:1.6,dash:r.id==='base'?[7,3]:undefined});}if(df.truth!==undefined)sers.push({pts:[[0,df.truth],[P.T,df.truth]],col:TRUTH,lw:1.4,dash:[5,4]});}
 for(const s of sers)for(const p of s.pts){if(p[1]===null||!isFinite(p[1]))continue;if(p[1]<lo)lo=p[1];if(p[1]>hi)hi=p[1];}
 if(df.fixed){lo=df.fixed[0];hi=df.fixed[1];}else if(df.log){lo=Math.max(1,lo);hi=Math.max(hi,lo*3);lo=Math.pow(10,Math.floor(Math.log10(lo)));hi=Math.pow(10,Math.ceil(Math.log10(hi)));}else{if(lo>0&&lo<.3*hi)lo=0;const pad=(hi-lo)*.08||1;if(lo!==0)lo-=pad;hi+=pad;}
 const Yv=v=>df.log?Tp+(1-(Math.log10(Math.max(v,lo))-Math.log10(lo))/(Math.log10(hi)-Math.log10(lo)))*ph:Tp+(1-(v-lo)/(hi-lo))*ph;
